<form method="GET" action="{{ $filterAction }}" class="panel report-filters"><div class="report-filter-grid"><label>Search transactions<input name="q" value="{{ request('q') }}" maxlength="100" placeholder="Reference, product name or SKU"></label><label>Branch<select name="branch_id" aria-label="Report branch"><option value="">All accessible branches</option>@foreach($branches as $b)<option value="{{ $b->id }}" @selected(request('branch_id')==$b->id)>{{ $b->name }}</option>@endforeach</select></label><label>Product<select name="product_id" aria-label="Report product"><option value="">All products</option>@foreach($products as $p)<option value="{{ $p->id }}" @selected(request('product_id')==$p->id)>{{ $p->name }} · {{ $p->sku }}</option>@endforeach</select></label><label>From date<input type="date" name="from" value="{{ request('from') }}"></label><label>To date<input type="date" name="to" value="{{ request('to') }}"></label><label>Status<select name="status" aria-label="Report status"><option value="">All statuses</option><option value="completed" @selected(request('status')==='completed')>Completed</option><option value="returned" @selected(request('status')==='returned')>Returned</option></select></label><label>Data source<select name="source" aria-label="Report source"><option value="">All sources</option>@foreach(['web','csv','api','demo'] as $source)<option value="{{ $source }}" @selected(request('source')===$source)>{{ strtoupper($source) }}</option>@endforeach</select></label><label>Sort transactions<select name="sort" aria-label="Report sort"><option value="newest" @selected(!request('sort') || request('sort')==='newest')>Newest first</option><option value="oldest" @selected(request('sort')==='oldest')>Oldest first</option><option value="amount_desc" @selected(request('sort')==='amount_desc')>Amount: high to low</option><option value="amount_asc" @selected(request('sort')==='amount_asc')>Amount: low to high</option></select></label></div><div class="report-filter-actions"><span>Dates use Africa/Lagos. Leave dates blank for all recorded sales.</span><a class="text-link" href="{{ $filterAction }}">Clear filters</a><button class="button">Apply filters</button></div></form>
